<?php

namespace App\Services\Admin\Nfc;

use App\NfcCardKey;
use App\User;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\File;
use Illuminate\Support\Facades\Mail;
use Illuminate\Support\Str;

/**
 * NFC activation keys (nfc_card_keys).
 *
 * - key_type "online": created for a paid NFC card order (one per card).
 *   key_type "offline": generated by an admin, optionally bundling a plan and
 *   an NFC card design (a voucher: key_status "active" until redeemed).
 * - link_status/card_id: the business card the physical NFC card opens.
 * - status: 1 visible, 2 deleted.
 * The URL written onto the chip is route('read.nfc.card', key).
 */
class NfcKeyService
{
    public const SHORT_CODES = [':logo', ':websitename', ':customername', ':activationcode', ':supportemail', ':supportphone', ':qrcode'];

    public function keyLength(): int
    {
        return max(6, (int) DB::table('config')->where('config_key', 'nfc_character_limit')->value('config_value') ?: 12);
    }

    public function newKey(string $type, ?string $planId = null, ?string $designId = null): NfcCardKey
    {
        $key                         = new NfcCardKey();
        $key->nfc_card_key_id        = uniqid();
        $key->key_type               = $type;
        $key->unqiue_key             = Str::random($this->keyLength());
        $key->associated_plan_id     = $planId;
        $key->associated_nfc_card_id = $designId;

        if ($planId && $designId) {
            $key->key_status = 'active';
        }

        $key->save();

        return $key;
    }

    /** @return array<int, string> the generated keys */
    public function generate(int $count, ?string $planId, ?string $designId): array
    {
        return DB::transaction(fn () => collect(range(1, $count))
            ->map(fn () => $this->newKey('offline', $planId, $designId)->unqiue_key)
            ->all());
    }

    public function link(NfcCardKey $key, string $cardId): void
    {
        $key->forceFill(['card_id' => $cardId, 'link_status' => 'linked', 'status' => 1])->save();
    }

    public function unlink(NfcCardKey $key): void
    {
        $key->forceFill(['card_id' => null, 'link_status' => 'unlinked', 'status' => 1])->save();
    }

    public function readUrl(string $key): string
    {
        return route('read.nfc.card', $key);
    }

    /** Where the QR code on the greeting letter points: the customer activation page. */
    public function activationUrl(string $key): string
    {
        return route('user.activate.nfc.card') . '?id=' . urlencode($key);
    }

    /** Stored greeting letter HTML (config "nfc_greetings"). */
    public function template(): string
    {
        return (string) DB::table('config')->where('config_key', 'nfc_greetings')->value('config_value');
    }

    public function saveTemplate(string $html): void
    {
        DB::table('config')->where('config_key', 'nfc_greetings')->update(['config_value' => $html]);
    }

    /** Values for the short codes, except :qrcode which is placed by the caller. */
    public function shortCodeValues(string $key, ?string $customerName): array
    {
        $settings = DB::table('settings')->first();
        $config   = DB::table('config')->whereIn('config_key', ['invoice_email', 'invoice_phone'])->pluck('config_value', 'config_key');

        return [
            ':logo'           => asset($settings->site_logo ?? ''),
            '%3Alogo'         => asset($settings->site_logo ?? ''),
            ':websitename'    => config('app.name'),
            ':customername'   => $customerName ?: __('Customer'),
            ':activationcode' => $key,
            ':supportemail'   => $config['invoice_email'] ?: 'N/A',
            ':supportphone'   => $config['invoice_phone'] ?: 'N/A',
        ];
    }

    /** Name of the customer who owns the card this key is linked to. */
    public function ownerName(NfcCardKey $key): ?string
    {
        if (! $key->card_id) {
            return null;
        }

        return DB::table('business_cards')
            ->join('users', 'users.user_id', '=', 'business_cards.user_id')
            ->where('business_cards.card_id', $key->card_id)
            ->value('users.name');
    }

    /**
     * Email the greeting letter with the QR code (PNG data URL from the browser).
     * Returns false when the email could not be sent.
     */
    public function sendGreeting(NfcCardKey $key, string $email, ?string $customerName, ?string $qrDataUrl): bool
    {
        $values = $this->shortCodeValues($key->unqiue_key, $customerName);
        $html   = str_replace(array_keys($values), array_values($values), $this->template());

        $qrPath = null;
        if ($qrDataUrl && preg_match('/^data:image\/png;base64,(.+)$/', $qrDataUrl, $match)) {
            $qrPath = storage_path('app/tmp/nfc-qr-' . uniqid() . '.png');
            File::ensureDirectoryExists(dirname($qrPath));
            File::put($qrPath, base64_decode(str_replace(' ', '+', $match[1])));
        }

        // The mail view swaps this placeholder for the embedded QR image.
        $html = str_replace(':qrcode', $qrPath ? '<div id="activateQrCode"></div>' : '', $html);

        try {
            if ($qrPath) {
                Mail::to($email)->send(new \App\Mail\NFCGreetingMail($html, $qrPath));
            } else {
                Mail::html($html, fn ($message) => $message->to($email)->subject(__('NFC Greeting Mail')));
            }

            return true;
        } catch (\Throwable $e) {
            report($e);

            return false;
        } finally {
            if ($qrPath) {
                File::delete($qrPath);
            }
        }
    }

    /** Customer name for an email address, if it belongs to a customer. */
    public function customerNameFor(string $email): ?string
    {
        return User::where('role_id', 2)->where('email', $email)->value('name');
    }
}
